    function log_sasetsu(message) { if (DEBUG_SASETSU) { console.log(`SASETSU_STATUS: ${message}`); } }
    function extractValue(rawValue, defaultValue = '--') { if (rawValue === undefined || rawValue === null) return defaultValue; let valueToProcess = Array.isArray(rawValue) && rawValue.length > 0 ? rawValue[0] : rawValue; return String(valueToProcess) || defaultValue; }
    function updateField(id, value) { const el = document.getElementById(id); if (el) { el.innerText = value; } }
    function updateProgressBar(barId, valueId, reasonId, rawValue, rawReason, min, max) { const barEl = document.getElementById(barId); const valEl = document.getElementById(valueId); const reasonEl = document.getElementById(reasonId); if (!barEl || !valEl || !reasonEl) { return; } const numericString = extractValue(rawValue, String(min)); let numericValue = parseFloat(numericString); if (isNaN(numericValue)) { valEl.innerText = numericString; barEl.style.width = '0%'; } else { valEl.innerText = numericString; numericValue = Math.max(min, Math.min(max, numericValue)); const percentage = max === min ? 0 : ((numericValue - min) / (max - min)) * 100; barEl.style.width = `${Math.max(0, Math.min(100, percentage))}%`; } reasonEl.innerText = extractValue(rawReason, '...'); }

    function populateFields(sourceData, sourceName = "data") {
        log_sasetsu(`Populating fields from "${sourceName}".`);
        const world = sourceData.世界 || {};
        const sasetsu = sourceData.高坂紗雪 || {};
        const kenichi = sourceData.中村健一 || {};
        updateField('world-address', extractValue(world.地址)); updateField('world-date', extractValue(world.日期)); updateField('world-time', extractValue(world.时间));
        updateField('sasetsu-top', extractValue(sasetsu.上装)); updateField('sasetsu-bottom', extractValue(sasetsu.下装)); updateField('sasetsu-bra', extractValue(sasetsu.内衣)); updateField('sasetsu-panties', extractValue(sasetsu.内裤));
        updateProgressBar('sasetsu-corruption-bar', 'sasetsu-corruption', 'sasetsu-corruption-reason', sasetsu.堕落, sasetsu.堕落_更新原因, 0, 100);
        updateField('sasetsu-stage', extractValue(sasetsu.沉沦阶段));
        updateField('sasetsu-lips', extractValue(sasetsu.舌唇)); updateField('sasetsu-breasts', extractValue(sasetsu.胸乳)); updateField('sasetsu-vagina', extractValue(sasetsu.小穴)); updateField('sasetsu-anus', extractValue(sasetsu.菊穴)); updateField('sasetsu-womb', extractValue(sasetsu.子宫)); updateField('sasetsu-hands', extractValue(sasetsu.玉手)); updateField('sasetsu-feet', extractValue(sasetsu.玉足));
        updateField('sasetsu-posture', extractValue(sasetsu.动作姿势)); updateField('sasetsu-thoughts', extractValue(sasetsu.内心想法));
        updateField('kenichi-name', extractValue(kenichi.姓名)); updateField('kenichi-location', extractValue(kenichi.当前位置)); updateField('kenichi-posture', extractValue(kenichi.当前神态姿势)); updateField('kenichi-thoughts', extractValue(kenichi.内心想法));
        setTimeout(() => { window.dispatchEvent(new Event('resize')); }, 150);
    }

    let currentRetry = 0; const MAX_RETRIES = 8; const RETRY_DELAY = 300;
    async function fetchDataWithRetry(msgId) {
        log_sasetsu(`Attempting fetch for msgId: ${msgId} (Retry ${currentRetry}/${MAX_RETRIES})`);
        try {
            if (typeof getChatMessages !== 'function') { throw new Error("SillyTavern API not found."); }
            const messages = await getChatMessages(msgId);
            const latestMessage = messages && messages.length > 0 ? messages[0] : null;
            if (latestMessage && latestMessage.data && latestMessage.data.stat_data) {
                log_sasetsu(`Success! stat_data found for msgId: ${msgId}.`);
                populateFields(latestMessage.data.stat_data, "Live stat_data");
            } else {
                currentRetry++;
                if (currentRetry < MAX_RETRIES) {
                    log_sasetsu(`stat_data not ready. Retrying in ${RETRY_DELAY}ms...`);
                    setTimeout(() => fetchDataWithRetry(msgId), RETRY_DELAY);
                } else {
                    log_sasetsu('Max retries reached. Falling back to hardcoded data.');
                    populateFields(hardcodedInitialData, "Fallback hardcoded data");
                }
            }
        } catch (err) {
            log_sasetsu(`CRITICAL ERROR: ${err.message}. Using hardcoded data.`);
            populateFields(hardcodedInitialData, "Error fallback");
        }
    }

    try {
        const currentMessageId = getCurrentMessageId();
        fetchDataWithRetry(currentMessageId);
    } catch (e) {
        log_sasetsu(`Initial call failed: ${e.message}. Using hardcoded data.`);
        populateFields(hardcodedInitialData, "Initial call fail fallback");
    }
})();
</script>
