---
<%
const statData = getvar("stat_data");
let 堕落 = -1;
let 当前实际阶段 = "未初始化";

if (statData && statData.高坂紗雪) {
    const sxyData = statData.高坂紗雪;
    if (sxyData.堕落 && Array.isArray(sxyData.堕落) && sxyData.堕落.length > 0 && !isNaN(parseInt(sxyData.堕落[0]))) {
        堕落 = parseInt(sxyData.堕落[0]);
    }
    if (sxyData.沉沦阶段 && Array.isArray(sxyData.沉沦阶段) && sxyData.沉沦阶段.length > 0) {
        当前实际阶段 = String(sxyData.沉沦阶段[0]);
